describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      // New subtotal should be 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
    });

    it("works without priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 800 }), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(800);
    });
  });

  describe("inventory check", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when item not available", async () => {
      const cart = new Cart();
      cart.add(product(), 3);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "out of stock" }),
      };
      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: true, availableQuantity: 2 }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
      }
    });

    it("checks each line and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 1);
      const checker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: true });
          return Promise.resolve({ available: false, availableQuantity: 0 });
        }),
      };
      await expect(
        cart.checkout({ inventoryChecker: checker }),
      ).rejects.toThrow(InventoryError);
    });
  });

  describe("async tax provider", () => {
    it("uses async tax rate for totals computation", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=1000, no discount, tax=10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(provider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=1000, discount=200, discounted=800, tax=10% of 800=80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });

    it("includes shipping with async tax", async () => {
      const cart = new Cart({
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(product({ unitPriceCents: 2000 }), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=2000, discount=0, tax=5% of 2000=100, shipping=500
      // total=2000+100+500=2600
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(2600);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline integration", () => {
    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(300),
      });
      cart.add(product({ id: "x", unitPriceCents: 500 }), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // After refresh: 600 * 2 = 1200 subtotal
      // Discount: 10% of 1200 = 120
      // Discounted subtotal: 1080
      // Tax: 8% of 1080 = 86 (floor)
      // Shipping: 300
      // Total: 1080 + 86 + 300 = 1466
      expect(result.totals.subtotalCents).toBe(1200);
      expect(result.totals.discountCents).toBe(120);
      expect(result.totals.taxCents).toBe(86);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(1466);
    });

    it("returns refreshed lines in result", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1", unitPriceCents: 100 }), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(999),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(999);
    });
  });

  describe("region configuration", () => {
    it("passes configured region to async tax provider", async () => {
      const cart = new Cart({ region: "FR" });
      cart.add(product(), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      await cart.checkout({ asyncTaxProvider: provider });
      expect(provider.getRate).toHaveBeenCalledWith("FR");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for a negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative percent", () => {
      expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects percent over 100", () => {
      expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    });

    it("rejects NaN", () => {
      expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    });

    it("rejects Infinity", () => {
      expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
    });

    it("accepts 0 percent", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100 percent", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 exactly
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor = 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% returns the full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(9999)).toBe(9999);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(15_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when equal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });

    it("accepts a single policy", () => {
      expect(
        () => new CompositeDiscountPolicy([new NoDiscountPolicy()]),
      ).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 => sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new PercentageDiscountPolicy(80)],
        "sum",
      );
      // 80% + 80% = 160% of 1000 = 1600 (exceeds 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("ignores negative values from individual policies (clamps to 0)", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // max(0, -100) + 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining amount", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900 → 10% of 900 = 90 → total = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 100% of 1000 = 1000 → remaining 0 → 50% of 0 = 0 → total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // A: fixed 500 on 1000 → remaining 500 → 50% of 500 = 250 → total 750
      expect(policyA.computeDiscountCents(1000)).toBe(750);
      // B: 50% of 1000 = 500 → remaining 500 → fixed min(500, 500) = 500 → total 1000
      expect(policyB.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("default stacking mode", () => {
    it("defaults to sum mode", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum mode: 10% of 1000 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

