describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for lines with zero weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines: CartLine[] = [
        { product: { id: "x", name: "X", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket for weight within first bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 250)], 1000)).toBe(300);
    });

    it("selects correct bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(500);
    });

    it("selects the highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300 * 2 = 600g → bracket 2 (upToGrams: 1000, costCents: 500)
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(500);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([makeLine("a", 250)], 1000)).toBe(300);
      expect(calc.computeShippingCents([makeLine("a", 750)], 1000)).toBe(500);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for duplicate product ids", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(
        RangeError,
      );
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes correct subtotal", () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1500);
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const tax: TaxCalculator = {
        computeTaxCents: (taxable) => Math.floor(taxable * 0.1),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=200, discounted=800, tax=80
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      expect(totals.taxCents).toBe(80);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product({ unitPriceCents: 500 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product({ unitPriceCents: 500 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("shipping receives discounted subtotal and lines", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(400),
      };
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800, // discounted subtotal
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 50,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 300,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=50, shipping=300
      // total = 900 + 50 + 300 = 1250
      expect(totals.totalCents).toBe(1250);
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: () => -50,
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });

  describe("defaults", () => {
    it("uses NoDiscountPolicy, NoTaxCalculator, FreeShippingCalculator, region US", () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 2000 }), 2);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(4000);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
  type InventoryChecker,
} from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
