describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      // New subtotal should be 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
    });

    it("works without priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 800 }), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(800);
    });
  });

  describe("inventory check", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when item not available", async () => {
      const cart = new Cart();
      cart.add(product(), 3);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "out of stock" }),
      };
      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: true, availableQuantity: 2 }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
      }
    });

    it("checks each line and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 1);
      const checker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: true });
          return Promise.resolve({ available: false, availableQuantity: 0 });
        }),
      };
      await expect(
        cart.checkout({ inventoryChecker: checker }),
      ).rejects.toThrow(InventoryError);
    });
  });

  describe("async tax provider", () => {
