      // New subtotal should be 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
    });

    it("works without priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 800 }), 1);
