      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=1000, no discount, tax=10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(provider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=1000, discount=200, discounted=800, tax=10% of 800=80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });

    it("includes shipping with async tax", async () => {
      const cart = new Cart({
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(product({ unitPriceCents: 2000 }), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=2000, discount=0, tax=5% of 2000=100, shipping=500
      // total=2000+100+500=2600
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(2600);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline integration", () => {
    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(300),
      });
      cart.add(product({ id: "x", unitPriceCents: 500 }), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // After refresh: 600 * 2 = 1200 subtotal
      // Discount: 10% of 1200 = 120
      // Discounted subtotal: 1080
      // Tax: 8% of 1080 = 86 (floor)
      // Shipping: 300
      // Total: 1080 + 86 + 300 = 1466
      expect(result.totals.subtotalCents).toBe(1200);
      expect(result.totals.discountCents).toBe(120);
      expect(result.totals.taxCents).toBe(86);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(1466);
    });

    it("returns refreshed lines in result", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1", unitPriceCents: 100 }), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(999),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(999);
    });
  });

  describe("region configuration", () => {
    it("passes configured region to async tax provider", async () => {
      const cart = new Cart({ region: "FR" });
      cart.add(product(), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      await cart.checkout({ asyncTaxProvider: provider });
      expect(provider.getRate).toHaveBeenCalledWith("FR");
    });
  });
});
